import sqlite3
import sys
import time
import hashlib
import base64

DB_FILE = 'accounts.db'

# Create a connection to the SQLite database
conn = sqlite3.connect(DB_FILE)
cursor = conn.cursor()

# Create the accounts table if it doesn't exist
cursor.execute('''
CREATE TABLE IF NOT EXISTS accounts (
    username TEXT PRIMARY KEY,
    email TEXT,
    password_digest BLOB
)''')
conn.commit()

def hash_password(password):
    return hashlib.sha256(password.encode()).digest()

def add_account(username, email, password):
    password_digest = hash_password(password)
    try:
        cursor.execute('INSERT INTO accounts (username, email, password_digest) VALUES (?, ?, ?)', (username, email, password_digest))
        conn.commit()
        return 'added'
    except sqlite3.IntegrityError:
        return 'exists'

def find_account(field, value):
    if field not in ['username', 'email']:
        return 'none'
    cursor.execute(f'SELECT username FROM accounts WHERE {field} = ?', (value,))
    result = cursor.fetchone()
    return result[0] if result else 'none'

def login(username, password, ttl_seconds):
    cursor.execute('SELECT password_digest FROM accounts WHERE username = ?', (username,))
    result = cursor.fetchone()
    if result and result[0] == hash_password(password):
        expiration_time = int(time.time()) + ttl_seconds
        pass_string = base64.urlsafe_b64encode(f'{username}:{expiration_time}'.encode()).decode().rstrip('=')
        return pass_string
    return 'denied'

def check_pass(pass_string):
    try:
        decoded = base64.urlsafe_b64decode(pass_string + '==').decode()
        username, expiration_time = decoded.split(':')
        if int(time.time()) < int(expiration_time):
            cursor.execute('SELECT username FROM accounts WHERE username = ?', (username,))
            if cursor.fetchone():
                return f'valid {username}'
    except Exception:
        pass
    return 'invalid'

# Main loop to read commands from stdin
for line in sys.stdin:
    command = line.strip().split()
    if not command:
        continue
    cmd = command[0]
    if cmd == 'add' and len(command) == 4:
        print(add_account(command[1], command[2], command[3]))
    elif cmd == 'find' and len(command) == 3:
        print(find_account(command[1], command[2]))
    elif cmd == 'login' and len(command) == 4:
        print(login(command[1], command[2], int(command[3])))
    elif cmd == 'check' and len(command) == 2:
        print(check_pass(command[1]))
    else:
        print('invalid command')

conn.close()
